const submitAppeal = `-- name: SubmitAppeal :one

UPDATE seller_violations SET
  appealed                  = true,
  appeal_reason             = $2,
  appeal_evidence_asset_ids = $3,
  appeal_status             = 'pending',
  appeal_submitted_at       = NOW(),
  updated_at                = NOW()
WHERE id = $1
  AND appealed = false
  AND status = 'enforced'   -- revoked 不可申訴
RETURNING id, seller_id, source_seller_report_id, source_food_safety_report_id, category, severity, penalty_type, penalty_amount_cents, description, public_summary, effective_at, expires_at, status, revoked_at, revoked_reason, appealed, appeal_reason, appeal_evidence_asset_ids, appeal_status, appeal_submitted_at, appeal_decided_at, appeal_decision_reason, appeal_decided_by_admin_id, created_by_admin_id, created_at, updated_at
`

type SubmitAppealParams struct {
	ID                     int64           `db:"id" json:"id"`
	AppealReason           *string         `db:"appeal_reason" json:"appeal_reason"`
	AppealEvidenceAssetIds json.RawMessage `db:"appeal_evidence_asset_ids" json:"appeal_evidence_asset_ids"`
}

// ========== Appeal ==========
// 賣家提交申訴；限申訴一次 → 由 only-if condition `appealed = false` enforce。
// 重複呼叫 RowsAffected=0，application 回 409。
func (q *Queries) SubmitAppeal(ctx context.Context, arg SubmitAppealParams) (SellerViolation, error) {
	row := q.db.QueryRow(ctx, submitAppeal, arg.ID, arg.AppealReason, arg.AppealEvidenceAssetIds)
	var i SellerViolation
	err := row.Scan(
		&i.ID,
		&i.SellerID,
		&i.SourceSellerReportID,
		&i.SourceFoodSafetyReportID,
		&i.Category,
		&i.Severity,
		&i.PenaltyType,
		&i.PenaltyAmountCents,
		&i.Description,
		&i.PublicSummary,
		&i.EffectiveAt,
		&i.ExpiresAt,
		&i.Status,
		&i.RevokedAt,
		&i.RevokedReason,
		&i.Appealed,
		&i.AppealReason,
		&i.AppealEvidenceAssetIds,
		&i.AppealStatus,
		&i.AppealSubmittedAt,
		&i.AppealDecidedAt,
		&i.AppealDecisionReason,
		&i.AppealDecidedByAdminID,
		&i.CreatedByAdminID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
